{
  "appearance_facts": [
    {
      "location": "top center, approx x=580, y=55",
      "fact": "Bold black title reads 'Increasing River Restoration Capacity from 2018 to 2023'. This is a strong visual cue for the intended trend direction."
    },
    {
      "location": "plot area, x from approx 105 to 950, y from approx 150 to 760",
      "fact": "A single solid blue line chart is plotted against a white background. The line is the only data series."
    },
    {
      "location": "line segment 2018 to 2019",
      "fact": "The line starts high on the left (2018) and slopes downward to a local minimum at 2019."
    },
    {
      "location": "line segment 2019 to 2020",
      "fact": "The line slopes sharply upward from 2019 to a peak at 2020."
    },
    {
      "location": "line segment 2020 to 2021",
      "fact": "The line slopes downward from the 2020 peak to 2021."
    },
    {
      "location": "line segment 2021 to 2023",
      "fact": "The line is nearly flat with a very slight downward slope from 2021 through 2023, ending at the right edge."
    },
    {
      "location": "y-axis, left side",
      "fact": "Vertical axis line with tick marks and labels. The scale runs from 0 at the bottom to 2,800 near the top."
    },
    {
      "location": "x-axis, bottom",
      "fact": "Horizontal axis line with tick marks for years 2018 through 2023."
    }
  ],
  "printed_facts": [
    {
      "location": "y-axis label, rotated text at approx x=40, y=450",
      "fact": "Axis title is 'Capacity Index'."
    },
    {
      "location": "y-axis ticks",
      "fact": "Numeric tick labels are 0, 400, 800, 1,200, 1,600, 2,000, 2,400, and 2,800."
    },
    {
      "location": "x-axis label, bottom center at approx x=530, y=850",
      "fact": "Axis title is 'Year'."
    },
    {
      "location": "x-axis ticks",
      "fact": "Year labels are 2018, 2019, 2020, 2021, 2022, 2023."
    },
    {
      "location": "data point 2018",
      "fact": "The line begins at 2018 with a Capacity Index value of approximately 2,800."
    },
    {
      "location": "data point 2019",
      "fact": "The line is at a local minimum of approximately 2,400 in 2019."
    },
    {
      "location": "data point 2020",
      "fact": "The line reaches its maximum value of approximately 2,850 in 2020."
    },
    {
      "location": "data point 2021",
      "fact": "The line is at approximately 2,600 in 2021."
    }
  ],
  "public_definitions": [
    "Use the dashboard trend as the basis for selecting the most appropriate operational route for this record.",
    "Assess the river restoration capacity dashboard for the 2018-2023 review window and send the record to the downstream route that best matches the overall dashboard trend."
  ],
  "uncertain": [
    "The exact Capacity Index values for 2022 and 2023 are not explicitly labeled, but the line appears to hover just above 2,400.",
    "There is a direct conflict between the chart title ('Increasing...') and the visual data trend (which shows a net decrease from 2018 to 2023 and a flat-to-declining trend from 2020 to 2023). It is unclear which element should take precedence for determining the 'overall dashboard trend'."
  ]
}
